const agent = new URLSearchParams(location.search).get("agent");const setup = document.getElementById("slack-agent-setup");if (setup && /^(?:chain|webops|publishing-house|videoops)\.[a-z0-9]+(?:-[a-z0-9]+)*$/.test(agent ?? "")){const [group,role] = agent.split(".");const portrait = (group === "videoops" ? "videoops-":"") + role;document.getElementById("slack-setup-command").textContent = 'npm exec --package=./kujo-slack-setup-0.1.1.tgz -- kujo-slack-setup "$HOME/.local/state/kujo/slack/' + agent + '" /path/to/kujo-agents --agent ' + agent;document.getElementById("slack-local-setup").href = "http://127.0.0.1:4396/setup?agent=" + agent;document.getElementById("slack-portrait-download").href = "/assets/slack-portraits/" + portrait + ".png";setup.hidden = false;document.getElementById("slack-select-agent").hidden = true;}